pub(super) async fn test_get_queued_runs_priority_ordering(storage: &Arc<AnyStorage>) {
    // Run A: priority 10, start_time 3000
    storage
        .create_run(&RunRecord {
            run_id: "a".to_string(),
            code_location_id: DEFAULT_CODE_LOCATION_ID.to_string(),
            job_name: Some("j".to_string()),
            status: RunStatus::Queued,
            start_time: 3000,
            end_time: None,
            tags: vec![],
            node_names: vec![],
            priority: 10,
            partition_key: None,
            block_reason: None,
            launched_by: LaunchedBy::Manual { user: None },
        })
        .await
        .unwrap();

    // Run B: priority 0, start_time 1000
    storage
        .create_run(&RunRecord {
            run_id: "b".to_string(),
            code_location_id: DEFAULT_CODE_LOCATION_ID.to_string(),
            job_name: Some("j".to_string()),
            status: RunStatus::Queued,
            start_time: 1000,
            end_time: None,
            tags: vec![],
            node_names: vec![],
            priority: 0,
            partition_key: None,
            block_reason: None,
            launched_by: LaunchedBy::Manual { user: None },
        })
        .await
        .unwrap();

    // Run C: priority 10, start_time 1000 (same priority as A, earlier time)
    storage
        .create_run(&RunRecord {
            run_id: "c".to_string(),
            code_location_id: DEFAULT_CODE_LOCATION_ID.to_string(),
            job_name: Some("j".to_string()),
            status: RunStatus::Queued,
            start_time: 1000,
            end_time: None,
            tags: vec![],
            node_names: vec![],
            priority: 10,
            partition_key: None,
            block_reason: None,
            launched_by: LaunchedBy::Manual { user: None },
        })
        .await
        .unwrap();

    let mut queued = storage.get_all_queued_runs().await.unwrap();
    assert_eq!(queued.len(), 3);
    // get_queued_runs is unordered — sort by priority DESC, start_time ASC (like coordinator)
    queued.sort_by(|a, b| {
        b.priority
            .cmp(&a.priority)
            .then(a.start_time.cmp(&b.start_time))
    });
    // Order: C (priority 10, earliest), A (priority 10, later), B (priority 0)
    assert_eq!(queued[0].run_id, "c");
    assert_eq!(queued[1].run_id, "a");
    assert_eq!(queued[2].run_id, "b");
}

